package koala.core

import kampfire.api.PostEndpoint
import kotlinx.browser.window
import kotlinx.serialization.json.Json
import org.w3c.fetch.RequestInit
import kotlin.js.json

inline fun <reified Sent, reified Returned> post(
    endpoint: PostEndpoint<Sent, Returned>,
    body: Sent,
    crossinline block: (Returned) -> Unit
) {
    window.fetch(endpoint.path, RequestInit(
        method = "POST",
        headers = json(
            "Content-Type" to "application/json",
        ),
        body = Json.encodeToString(body)
    )).then({ response ->
        response.text().then { text ->
            val returned: Returned = Json.decodeFromString(text)
            block(returned)
        }
    })
}