import koala.core.post
import koala.model.stateOf
import streetlight.model.Api
import streetlight.model.data.EventId
import streetlight.model.data.NewRequest
import streetlight.model.data.SongId

class EventPortal(
    private val eventId: EventId,
) {
    private val view = stateOf(EventPortalState())

    fun setSongId(songId: SongId, ) {
        view.set { it.copy(songId = songId) }
    }

    fun sendRequest() {
        val songId = view.now.songId ?: return
        val request = NewRequest(
            eventId = eventId,
            songId = songId,
            songName = null,
            isJoining = false,
            comment = null,
            requesterName = null
        )
        post(Api.RequestBox, request) {
            console.log(it)
        }
    }
}

data class EventPortalState(
    val songId: SongId? = null,
)